-- Full Spectrum grants: batch 6 (funder details from research notes dated 2026-11-01; pages not re-opened by us).
-- 10 new funders. Idempotent; safe to re-run.
-- Apply: supabase db query --linked -f supabase/fs-grants-batch6.sql
begin;
select count(*) as before_total from fs_grant_deadlines;

insert into fs_grant_deadlines (funder, program, kind, deadline_date, opens_date, amount, verified, url, notes, verified_on, level, project, priority, eligibility, match_required, status, gates, next_step, next_step_due)
select * from (values
('Sparkplug Foundation','Grants for emerging musicians and early-stage music organizations','dated','2026-11-01'::date,null::date,'$1,000-$20,000 (most $10,000-$15,000)',false,'https://www.sparkplugfoundation.org/information/','LETTER OF INTENT DUE 2026-11-01 (today when added); invited full applications due Nov 16. Music proposals need a music sample. EXCLUDES computers/technology equipment, visual arts, religious orgs/projects, budgets over $1 million. Fit is a youth-created ORIGINAL music project rooted in South Side stories, not a general class or equipment ask. Screen the restrictions before rushing; if the LOI window is missed, ask whether a later cycle exists.','2026-11-01'::date,'foundation','djclass',2,'Emerging musicians / early-stage orgs; no tech equipment',null,'to_research','{g0}'::text[],'Decide today whether an original-music project fits; if yes, submit the LOI or ask Sparkplug about a late LOI','2026-11-01'::date),
('Sigma Alpha Iota Philanthropies','Community Arts Grants','expected','2027-03-01'::date,null,'up to $5,000',false,'https://www.sai-national.org/philanthropies/scholarships-grants-awards.html','Deadlines Mar 1 and Jun 1 2027, 11:59 pm ET (reported by a third-party listing: confirm on the SAI page). Eligible uses include music education, instruments and technical equipment, GUEST ARTIST FEES, performance production. Needs a music-focused mission, budget up to $3 million, two support letters, and SPONSORSHIP BY AN SAI MEMBER OR CHAPTER in good standing. First task: find a local SAI chapter and confirm DJ-program fit.','2026-11-01'::date,'foundation','djclass',2,'Music mission; SAI member or chapter sponsor; two support letters',null,'to_research','{g0,g4}'::text[],'Find a Chicago-area SAI chapter willing to sponsor; confirm DJ fit and dates on the SAI page','2027-01-15'::date),
('Union Pacific','Community Ties Local Grants','paused',null,null,'$5,000-$30,000 typical',true,'https://www.up.com/communities/philanthropic-giving/local-grants','2026 window was Apr 1-30; 2027 dates not announced. Priorities include cultural experiences, performing arts, neighborhood revitalization, youth development. Must serve an eligible Union Pacific community (verify the list covers Chicago). EXCLUDES event sponsorship and general operating: structure as program support for the free DJ Lab.','2026-11-01'::date,'corporate','djclass',3,'Public charity serving a UP community; program support only',null,'to_research','{g0}'::text[],'Check the community list and watch for the 2027 window (April)',null),
('Meijer','Charitable Donations','rolling',null,null,'not published',true,'https://meijercommunity.com/support','Online request; allow 60 DAYS for review. 501(c)(3) with a current signed W-9. Explain the tie to a community Meijer serves (confirm a Meijer near Rainbow Beach / South Shore). Ask for student meals or refreshments so money stays for instructors and artists.','2026-11-01'::date,'corporate','wednesdays',3,'501(c)(3); signed W-9; community Meijer serves',null,'to_research','{g0}'::text[],'Confirm a nearby Meijer, then file the request 60+ days ahead of the event',null),
('Whole Foods Market','In-Kind Donations','rolling',null,null,'in-kind product only',true,'https://www.wholefoodsmarket.com/company-info/newsroom/in-kind-donations','Considered year-round; contact local store leadership directly. Verified 501(c)(3) benefiting the store''s surrounding community. NO cash or gift cards. Priority to orgs without another donation or sponsorship that calendar year.','2026-11-01'::date,'corporate','wednesdays',3,'501(c)(3); store community benefit',null,'to_research','{}'::text[],'Ask the nearest store for student refreshments for one named event',null),
('Mariano''s / Roundy''s Fund (Kroger)','Community donations and foundation requests','rolling',null,null,'small cash or in-kind',true,'https://www.marianos.com/i/community/giving-back','Store donation requests need at least 4 WEEKS notice; foundation requests need at least 12 WEEKS. 501(c)(3). Mainly hunger relief. Submit to ONE banner only (duplicates removed). Corporate requests use the Kroger portal.','2026-11-01'::date,'corporate','wednesdays',3,'501(c)(3); hunger-relief focus',null,'to_research','{}'::text[],'Pick one banner (Mariano''s or another Kroger brand) and ask for food for students',null),
('Chicago Fire FC Foundation','Donation Requests (auction item)','rolling',null,null,'donated item only',true,'https://matchcenter.chicagofirefc.com/foundation/donation-requests','Online, at least 6 WEEKS before the fundraiser. Needs IRS determination letter; within 75 miles of Chicago. One item per calendar year. NO monetary grants or sponsorships. Useful only if Full Spectrum holds an auction.','2026-11-01'::date,'corporate','org',3,'Determination letter; within 75 miles of Chicago',null,'to_research','{g0}'::text[],'Only if an auction is scheduled: request an item 6+ weeks ahead',null),
('Give A Note Foundation','Music Tech Empowers (school partner)','relationship',null,null,'not published',true,'https://www.giveanote.org/music-tech-empowers','Needs a PUBLIC SCHOOL partner: full-time educator, regular school-day class, dedicated room, reliable internet, admin support; Title I schools get priority. Not a direct Full Spectrum grant. Ask info@giveanote.org about selection and next intake.','2026-11-01'::date,'foundation','djclass',3,'Public school applies',null,'to_research','{g4}'::text[],'Email info@giveanote.org once a CPS teacher is interested',null),
('Save The Music Foundation','J Dilla Music Technology Grant (school partner)','relationship',null,null,'equipment and programming',true,'https://www.savethemusic.org/how-we-work/explore-music-tech/','Grades 9-12 electronic music production. Public-school partnership: funded certified music/audio teacher, dedicated classroom and secure storage, scheduled school-day instruction. School grants are invitation-based through district partnerships. Inquiries stmschool@savethemusic.org. Not a direct beach-program grant.','2026-11-01'::date,'foundation','djclass',3,'CPS high school with a certified teacher',null,'to_research','{g4}'::text[],'Introduce to a CPS high-school music teacher; email stmschool@savethemusic.org',null),
('Harbor Freight Tools','Giving Back (school-partner project)','rolling',null,null,'gift cards for tools and supplies',true,'https://harborfreightgivingback.com/donation-request-information/','Youth support targets K-12 PUBLIC schools (classroom projects, clubs); Ras Tafari''s general arts program does not qualify by itself. Nonprofit criteria include at least one year of tax-exempt status, local benefit, one request per calendar year. Idea: a school partner''s hands-on booth-building or reusable display project.','2026-11-01'::date,'corporate','wednesdays',3,'K-12 public school project; nonprofits need 1+ year tax-exempt',null,'to_research','{g4}'::text[],'Only with a school partner; otherwise skip',null)
) as v(funder,program,kind,deadline_date,opens_date,amount,verified,url,notes,verified_on,level,project,priority,eligibility,match_required,status,gates,next_step,next_step_due)
where not exists (select 1 from fs_grant_deadlines g where g.funder = v.funder and g.program = v.program);

select count(*) as after_total from fs_grant_deadlines;
commit;
